def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    cindy_bid = None
    highest_prev = 0.0
    urgent_opp = 0
    rich_opp = 0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        pbid = prev.get('bid')
        if pbid is not None:
            if pbid > highest_prev:
                highest_prev = pbid
            if oid == 'Cindy':
                cindy_bid = pbid
        if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 0) <= 3:
            urgent_opp += 1
        if opp.get('budget', 0) >= 200:
            rich_opp += 1

    my_urgent = (hp <= 3) or (no_water_days >= 2)
    tight_supply = supply <= 17
    loose_supply = supply >= 22

    target = DAILY_SALARY * 0.45

    if cindy_bid is not None:
        target = max(target, cindy_bid + 2.0)
    elif highest_prev > 0:
        target = max(target, highest_prev + 2.0)

    if loose_supply and not my_urgent:
        target *= 0.55
    elif tight_supply:
        target *= 1.18

    if urgent_opp >= 2:
        target *= 1.1
    if rich_opp >= 2:
        target *= 1.08

    if my_urgent:
        if cindy_bid is not None:
            target = max(target, cindy_bid + 6.0)
        else:
            target = max(target, DAILY_SALARY * 1.35)

    if hp <= 2 or no_water_days >= 3:
        target = max(target, DAILY_SALARY * 1.6)
        if cindy_bid is not None:
            target = max(target, cindy_bid + 10.0)

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve = DAILY_SALARY * 0.6

    affordable = max(0.0, budget - reserve)
    if my_urgent:
        affordable = budget

    bid = min(target, affordable if affordable > 0 else budget)

    if bid <= 0 and my_urgent:
        bid = budget
    elif bid <= 0:
        bid = min(budget, DAILY_SALARY * 0.2)

    if not my_urgent and loose_supply and highest_prev >= 120:
        bid = min(budget, DAILY_SALARY * 0.3)

    if bid > budget:
        bid = budget
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        cap = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, cap)

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent pressure
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Choose aggressiveness based on my HP and their prior pressure
    # If Cindy-like high pressure existed, try to undercut slightly while staying strong.
    # Also scale with supply: when supply is higher, water is cheaper, so bid less.
    supply_ratio = 0.0
    if (MAX_SUPPLY - MIN_SUPPLY) > 0:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    # Clamp
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    # Base bid targets
    base = DAILY_SALARY * (0.62 - 0.25 * supply_ratio)  # lower bid when supply is higher

    # Pressure adjustment from yesterday
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Likely someone is paying near ceiling; undercut but remain competitive
        base = max(base, highest_prev_bid * 0.92)
    elif highest_prev_bid >= DAILY_SALARY * 0.45:
        base = max(base, highest_prev_bid * 0.75)

    # Urgency adjustment
    if hp <= 1:
        base = max(base, DAILY_SALARY * 0.95)
    elif hp <= 3:
        base = max(base, DAILY_SALARY * 0.78)

    # If we've gone multiple days without water, increase bid
    if no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.85)

    # Ensure we don't bid above reasonable fraction of budget
    # Keep some budget for later days; but if low budget, bid what we can.
    budget_cap = budget
    if budget_cap > 0.0:
        # If budget is healthy, keep at most ~70% of it for this day
        budget_cap = min(budget_cap, DAILY_SALARY * 1.2, budget * 0.7)

    bid = min(base, budget_cap)
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    MY_WATER_REQ = 13
    MY_DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if not alive_opponents:
        return min(my_budget, MY_DAILY_SALARY * 0.1)

    base_bid = MY_DAILY_SALARY * 0.5

    if my_hp <= 2:
        base_bid = MY_DAILY_SALARY * 0.95
    elif my_hp <= 4:
        base_bid = MY_DAILY_SALARY * 0.8
    elif my_no_water_days > 0:
        base_bid = MY_DAILY_SALARY * 0.7

    days_remaining = EPISODE_DAYS - current_day
    if days_remaining <= 3 and my_budget > MY_DAILY_SALARY * 3:
        base_bid *= 1.1

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= MY_DAILY_SALARY * 0.7:
            if my_hp <= 3:
                base_bid = max(base_bid, highest_prev_bid + 5)
            else:
                base_bid = max(base_bid, highest_prev_bid * 0.9)
        elif highest_prev_bid > MY_DAILY_SALARY * 0.4:
            base_bid = max(base_bid, highest_prev_bid * 1.05)

    if current_supply < MY_WATER_REQ * 1.5 and num_alive_opponents >= 1:
        base_bid *= 1.15
    elif current_supply < MY_WATER_REQ * 2 and num_alive_opponents >= 2:
        base_bid *= 1.1

    final_bid = min(my_budget, base_bid)
    final_bid = max(0.0, final_bid)

    return round(final_bid, 2)

